<?php
require_once __DIR__ . '/../../includes/auth-check.php';
require_once __DIR__ . '/../../includes/admin-ui.php';
admin_require_permission($pdo,$admin,'manage_pages');
$search=trim(substr(request_string($_GET, 'q', ''),0,100));$status=in_array(($_GET['status']??''),['draft','published','archived'],true)?(string)$_GET['status']:'';
$sql='SELECT id,slug,title,status,noindex,legacy_file,updated_at FROM site_pages WHERE 1=1';$params=[];if($search!==''){$sql.=' AND (title LIKE :title_q OR slug LIKE :slug_q)';$searchValue='%'.str_replace(['%','_'],['\\%','\\_'],$search).'%';$params['title_q']=$searchValue;$params['slug_q']=$searchValue;}if($status!==''){$sql.=' AND status=:status';$params['status']=$status;}$sql.=' ORDER BY FIELD(status,\'draft\',\'published\',\'archived\'),updated_at DESC LIMIT 250';$query=$pdo->prepare($sql);$query->execute($params);$pages=$query->fetchAll();
admin_header($pdo,$admin,'Custom pages');
?>
<div class="admin-actions" style="margin-bottom:1rem"><a class="button button-primary" href="<?=e(app_url('admin/pages/edit.php'))?>">＋ New page</a><span class="admin-badge"><?=count($pages)?> shown · max 250</span></div><form class="admin-filter" method="get"><input type="search" name="q" value="<?=e($search)?>" placeholder="Search title or slug"><select name="status"><option value="">All statuses</option><?php foreach(['draft','published','archived'] as $option):?><option value="<?=e($option)?>" <?=$status===$option?'selected':''?>><?=e(ucfirst($option))?></option><?php endforeach;?></select><button class="button button-small" type="submit">Filter</button></form>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Page</th><th>Status</th><th>Indexing</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($pages as $page):?><tr><td><strong><?=e($page['title'])?></strong><br><code>/pages/<?=e($page['slug'])?></code><?php if($page['legacy_file']):?><br><small>Legacy alias: <?=e($page['legacy_file'])?></small><?php endif;?></td><td><span class="admin-badge admin-badge--<?=e($page['status'])?>"><?=e(ucfirst($page['status']))?></span></td><td><?=$page['noindex']?'noindex':'index'?></td><td><?=e($page['updated_at'])?></td><td><div class="admin-actions"><a href="<?=e(app_url('admin/pages/edit.php?id='.(int)$page['id']))?>">Edit</a><?php if($page['status']==='published'):?><a href="<?=e(app_url('pages/'.$page['slug']))?>" target="_blank" rel="noopener">View</a><?php endif;?><form method="post" data-confirm="Delete this page?"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$page['id']?>"><button class="admin-danger" formaction="<?=e(app_url('admin/pages/delete.php'))?>" type="submit">Delete</button></form></div></td></tr><?php endforeach;?><?php if(!$pages):?><tr><td colspan="5">No pages found.</td></tr><?php endif;?></tbody></table></div>
<?php admin_footer(); ?>
